     1	package com.loja.api;
     2	
     3	import io.javalin.Javalin;
     4	import com.loja.model.*;
     5	import com.loja.service.OrderService;
     6	import com.loja.service.CheckoutException;
     7	import com.loja.service.OrderException;
     8	
     9	public class OrderEndpoint {
    10	    private final OrderService orderService;
    11	
    12	    public OrderEndpoint(OrderService orderService) {
    13	        this.orderService = orderService;
    14	    }
    15	
    16	    public void register(Javalin app) {
    17	        app.post("/orders", ctx -> {
    18	            try {
    19	                CheckoutRequest request = ctx.bodyAsClass(CheckoutRequest.class);
    20	                Order order = orderService.createOrder(request);
    21	                ctx.status(201).json(order);
    22	            } catch (CheckoutException e) {
    23	                ctx.status(getHttpStatus(e.errorCode)).json(new ErrorResponse(e.errorCode));
    24	            }
    25	        });
    26	
    27	        app.get("/orders/{id}", ctx -> {
    28	            Order order = orderService.findOrder(ctx.pathParam("id"));
    29	            if (order == null) {
    30	                ctx.status(404).json(new ErrorResponse("ORDER_NOT_FOUND"));
    31	                return;
    32	            }
    33	            ctx.status(200).json(order);
    34	        });
    35	
    36	        app.post("/orders/{id}/payment", ctx -> {
    37	            try {
    38	                PaymentRequest payment = ctx.bodyAsClass(PaymentRequest.class);
    39	                Order order = orderService.processPayment(
    40	                    ctx.pathParam("id"),
    41	                    payment.transactionId,
    42	                    payment.paidAt
    43	                );
    44	                ctx.status(200).json(order);
    45	            } catch (OrderException e) {
    46	                ctx.status(e.httpStatus).json(new ErrorResponse(e.errorCode));
    47	            }
    48	        });
    49	
    50	        app.post("/orders/{id}/shipment", ctx -> {
    51	            try {
    52	                ShipmentRequest shipment = ctx.bodyAsClass(ShipmentRequest.class);
    53	                Order order = orderService.shipOrder(ctx.pathParam("id"), shipment.trackingCode);
    54	                ctx.status(200).json(order);
    55	            } catch (OrderException e) {
    56	                ctx.status(e.httpStatus).json(new ErrorResponse(e.errorCode));
    57	            }
    58	        });
    59	
    60	        app.post("/orders/{id}/delivery", ctx -> {
    61	            try {
    62	                Order order = orderService.deliverOrder(ctx.pathParam("id"));
    63	                ctx.status(200).json(order);
    64	            } catch (OrderException e) {
    65	                ctx.status(e.httpStatus).json(new ErrorResponse(e.errorCode));
    66	            }
    67	        });
    68	
    69	        app.post("/orders/{id}/cancellation", ctx -> {
    70	            try {
    71	                Order order = orderService.cancelOrder(ctx.pathParam("id"));
    72	                ctx.status(200).json(order);
    73	            } catch (OrderException e) {
    74	                ctx.status(e.httpStatus).json(new ErrorResponse(e.errorCode));
    75	            }
    76	        });
    77	    }
    78	
    79	    private int getHttpStatus(String errorCode) {
    80	        return switch (errorCode) {
    81	            case "CARRIER_UNAVAILABLE" -> 503;
    82	            default -> 422;
    83	        };
    84	    }
    85	}
