    10	    @Override
    11	    public Double calculateDiscount(Double productsSubtotal, List<OrderItem> items, ProductProvider productProvider) {
    12	        Map<String, Integer> quantities = items.stream()
    13	            .collect(Collectors.groupingBy(item -> item.sku, Collectors.summingInt(item -> item.quantity)));
    14	
    15	        Double totalDiscount = 0.0;
    16	        for (var entry : quantities.entrySet()) {
    17	            String sku = entry.getKey();
    18	            Integer quantity = entry.getValue();
    19	
    20	            if (quantity >= 3) {
    21	                Product product = productProvider.getProduct(sku);
    22	                if (product != null) {
    23	                    int freeitems = quantity / 3;
    24	                    totalDiscount += product.price * freeitems;
    25	                }
    26	            }
    27	        }
    28	
    29	        return Money.round(totalDiscount);
    30	    }
