     6	public class Database {
     7	    private final String url;
     8	    private final String user;
     9	    private final String password;
    10	
    11	    public Database() {
    12	        this.url = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/order_service");
    13	        this.user = System.getenv().getOrDefault("DB_USER", "postgres");
    14	        this.password = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
    15	    }
    16	
    17	    public void initialize() {
    18	        try {
    19	            Class.forName("org.postgresql.Driver");
    20	            executeSchema();
    21	        } catch (ClassNotFoundException e) {
    22	            throw new RuntimeException("PostgreSQL driver not found", e);
    23	        }
    24	    }
    25	
    26	    private void executeSchema() {
    27	        String schema = readSchemaFile();
    28	        try (Connection conn = getConnection();
    29	             Statement stmt = conn.createStatement()) {
    30	            for (String statement : schema.split(";")) {
    31	                if (statement.trim().isEmpty()) continue;
    32	                stmt.execute(statement);
    33	            }
    34	        } catch (SQLException e) {
    35	            throw new RuntimeException("Failed to initialize schema", e);
    36	        }
    37	    }
    38	
    39	    private String readSchemaFile() {
    40	        try (Scanner scanner = new Scanner(
    41	            Database.class.getResourceAsStream("/schema.sql"),
    42	            "UTF-8")) {
    43	            return scanner.useDelimiter("\\A").next();
    44	        }
    45	    }
    46	
    47	    public Connection getConnection() throws SQLException {
    48	        return DriverManager.getConnection(url, user, password);
    49	    }
