    14	    public Notification findById(String id) {
    15	        String sql = "SELECT id, type, order_id, cpf, status FROM notifications WHERE id = ?";
    16	        try (Connection conn = db.getConnection();
    17	             PreparedStatement stmt = conn.prepareStatement(sql)) {
    18	            stmt.setString(1, id);
    19	            try (ResultSet rs = stmt.executeQuery()) {
    20	                if (rs.next()) {
