    30	    public List<Notification> findByCpf(String cpf) {
    31	        String sql = "SELECT id, type, order_id, cpf, status FROM notifications WHERE cpf = ? ORDER BY id ASC";
    32	        List<Notification> notifications = new ArrayList<>();
    33	        try (Connection conn = db.getConnection();
    34	             PreparedStatement stmt = conn.prepareStatement(sql)) {
    35	            stmt.setString(1, cpf);
